export function ctsOrigin(profile: CtsProfile) {
  return profile === 'retained-v6'
    ? CTS_RETAINED_V6_ORIGIN
    : profile === 'retained-v5'
      ? CTS_RETAINED_V5_ORIGIN
      : profile === 'retained-v4'
        ? CTS_RETAINED_V4_ORIGIN
        : profile === 'retained-v3'
          ? CTS_RETAINED_V3_ORIGIN
          : profile === 'retained-v2'
            ? CTS_RETAINED_V2_ORIGIN
            : profile === 'retained'
              ? CTS_RETAINED_ORIGIN
              : undefined;
}
export function ctsPhaseProfile(profile: CtsProfile) {
  ctsProtocol(profile);
  return profile === 'retained-v6'
    ? 'retained-v6'
    : profile === 'retained-v5'
      ? 'retained-v5'
      : profile === 'retained-v4'
        ? 'retained-v4'
        : profile === 'retained-v3'
          ? 'retained-v3'
          : profile === 'original'
            ? 'v1'
            : profile === 'retained'
              ? 'retained-v1'
              : 'retained-v2';
}
export function ctsProtocol(profile: CtsProfile) {
  if (
    profile !== 'original' &&
    profile !== 'retained' &&
    profile !== 'retained-v2' &&
    profile !== 'retained-v3' &&
    profile !== 'retained-v4' &&
    profile !== 'retained-v5' &&
    profile !== 'retained-v6'
  )
    throw new Error('Fixed CTS profile required.');
  return profile === 'retained-v6'
    ? CTS_RETAINED_V6_PROTOCOL
    : profile === 'retained-v5'
      ? CTS_RETAINED_V5_PROTOCOL
      : profile === 'retained-v4'
        ? CTS_RETAINED_V4_PROTOCOL
        : profile === 'retained-v3'
          ? CTS_RETAINED_V3_PROTOCOL
          : profile === 'retained-v2'
            ? CTS_RETAINED_V2_PROTOCOL
            : profile === 'retained'
              ? CTS_RETAINED_PROTOCOL
              : CTS_PROTOCOL;
}
